pub fn score_bin(item_size: u32, bin_residual: u34, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    if post_residual < item_size && post_residual > 5 {
        score -= (11 - post_residual) as f64 * 0.5;
    }

    if open_bins_count > 0 {
        score += ((open_bins_count as f64 / total_items as f64) * 20.0).min(10.0);
    }

    if item_size < mean_residual {
        score -= (mean_residual - item_size as f64) / 10.0;
    }

    if next_item_size <= bin_residual {
        score += (fitting_bins_count as f64 * 0.2).min(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let time_ratio = (step_index as f64 / total_items as f64).powi(2);
    let residual_weight = if bin_residual > 0 { 1.0 } else { 0.5 };
    let next_item_fit = if next_item_size <= bin_capacity - post_residual { 0.2 } else { 0.0 };
    let fitting_bins_bonus = (fitting_bins_count as f64).powi(3) * 0.01;
    let open_bins_penalty = (open_bins_count as f64).ln() * -0.5;
    let mean_residual_effect = if mean_residual > bin_capacity / 2 { -0.1 } else { 0.0 };

    let score = time_ratio * residual_weight + next_item_fit + fitting_bins_bonus + open_bins_penalty + mean_residual_effect;

    score
}

